INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('HV-161608-1KG', 'npk-han-viet-16-16-8-te-goi-1kg', 'NPK Hàn-Việt 16-16-8+TE', 'Gói 1kg', 'han-viet', 'main', 33000, NULL, NULL, NULL, 100, '/assets/img/hv-161608-1kg.webp', '/assets/img/hv-161608-1kg.webp', 'Phân NPK phức hợp một hạt một màu, bổ sung Bo và Kẽm. Gói 1kg chiết lẻ tiện cho vườn nhỏ, rau màu, cây cảnh.', 'NPK Hàn-Việt do Công ty TNHH Phân bón Hàn-Việt (KVF) sản xuất bằng công nghệ hơi nước theo tiêu chuẩn Hàn Quốc, dạng phức hợp một hạt một màu nên mỗi hạt đều đủ đạm, lân, kali, bón ra cây hấp thu đồng đều.', '["Cây ra rễ mạnh, bộ lá xanh dày","Sinh trưởng khỏe, chống chịu sâu bệnh và thời tiết tốt hơn","Dùng bón lót và bón thúc cho mọi loại cây"]', 'Bón lót và bón thúc. Cây ăn trái 1–2 kg/cây/năm; cây công nghiệp 450–700 kg/ha/năm; lúa, bắp 300–400 kg/ha/vụ; rau màu 200–250 kg/ha/vụ. Lượng bón thay đổi theo đất và tình trạng cây.', 'Đạm tổng số (Nts) 16%, Lân hữu hiệu (P2O5hh) 16%, Kali hữu hiệu (K2Ohh) 8%, Bo (B) 310 ppm, Kẽm (Zn) 800 ppm, độ ẩm 2%.', 'Gói 1kg', '["Hàn Việt","Phân bón"]', '["rau-mau","chanh-day"]', NULL, NULL, NULL, 'Phân NPK phức hợp một hạt một màu, bổ sung Bo và Kẽm. Gói 1kg chiết lẻ tiện cho vườn nhỏ, rau màu, cây cảnh.', 1050, 25, 15, 5, 0, 1) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('HV-161616-1KG', 'npk-han-viet-16-16-16-te-goi-1kg', 'NPK Hàn-Việt 16-16-16+TE', 'Gói 1kg', 'han-viet', 'main', 35000, NULL, NULL, NULL, 100, '/assets/img/hv-161616-1kg.webp', '/assets/img/hv-161616-1kg.webp', 'Công thức cân đối đạm, lân, kali bằng nhau, bổ sung vi lượng. Dùng được cho hầu hết giai đoạn sinh trưởng.', 'NPK Hàn-Việt do Công ty TNHH Phân bón Hàn-Việt (KVF) sản xuất bằng công nghệ hơi nước theo tiêu chuẩn Hàn Quốc, dạng phức hợp một hạt một màu nên mỗi hạt đều đủ đạm, lân, kali, bón ra cây hấp thu đồng đều.', '["Dinh dưỡng cân đối cho cây phát triển đều","Bổ sung vi lượng (TE)","Phù hợp rau màu, cây ăn trái, hoa kiểng"]', 'Bón gốc rải đều quanh tán, xới nhẹ và tưới ẩm sau khi bón. Liều tham khảo như các dòng NPK Hàn-Việt cân đối: cây ăn trái 1–2 kg/cây/năm chia nhiều lần, rau màu 200–250 kg/ha/vụ.', 'Đạm (N) 16%, Lân (P2O5) 16%, Kali (K2O) 16%, bổ sung trung vi lượng (TE).', 'Gói 1kg', '["Hàn Việt","Phân bón"]', '["rau-mau","chanh-day"]', NULL, NULL, NULL, 'Công thức cân đối đạm, lân, kali bằng nhau, bổ sung vi lượng. Dùng được cho hầu hết giai đoạn sinh trưởng.', 1050, 25, 15, 5, 0, 2) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('HV-202015-1KG', 'npk-han-viet-20-20-15-te-goi-1kg', 'NPK Hàn-Việt 20-20-15+TE', 'Gói 1kg', 'han-viet', 'main', 37000, NULL, NULL, NULL, 100, '/assets/img/hv-202015-1kg.webp', '/assets/img/hv-202015-1kg.webp', 'Hàm lượng dinh dưỡng cao 55%, bổ sung Bo và Kẽm, chuyên bón thúc. Gói 1kg chiết lẻ.', 'NPK Hàn-Việt do Công ty TNHH Phân bón Hàn-Việt (KVF) sản xuất bằng công nghệ hơi nước theo tiêu chuẩn Hàn Quốc, dạng phức hợp một hạt một màu nên mỗi hạt đều đủ đạm, lân, kali, bón ra cây hấp thu đồng đều.', '["Đạm, lân cao giúp cây bật chồi, xanh lá nhanh","Bổ sung Bo, Kẽm","Tăng năng suất và chất lượng nông sản"]', 'Bón thúc. Lúa, bắp 250–350 kg/ha/vụ; cây công nghiệp 250–400 kg/ha/đợt; cây ăn trái 1–1,5 kg/cây/lần; rau, đậu 150–250 kg/ha/vụ.', 'Đạm tổng số (Nts) 20%, Lân hữu hiệu (P2O5hh) 20%, Kali hữu hiệu (K2Ohh) 15%, Bo (B) 310 ppm, Kẽm (Zn) 800 ppm, độ ẩm 2%.', 'Gói 1kg', '["Hàn Việt","Phân bón","Bán chạy"]', '["rau-mau","chanh-day"]', NULL, NULL, NULL, 'Hàm lượng dinh dưỡng cao 55%, bổ sung Bo và Kẽm, chuyên bón thúc. Gói 1kg chiết lẻ.', 1050, 25, 15, 5, 0, 3) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_