INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('HV-17717-50KG', 'npk-han-viet-17-7-17-te-bao-50kg', 'NPK Hàn-Việt 17-7-17+TE', 'Bao 50kg', 'han-viet', 'main', 0, NULL, NULL, NULL, 50, '/assets/img/hv-17717-50kg.webp', '/assets/img/hv-17717-50kg.webp', 'Phân NPK phức hợp một hạt một màu (hạt màu hồng), bao 50kg, mã HV02A. Giá bao lớn thay đổi theo đợt hàng và khu vực, liên hệ để nhận báo giá.', 'NPK Hàn-Việt do Công ty TNHH Phân bón Hàn-Việt (KVF) sản xuất bằng công nghệ hơi nước theo tiêu chuẩn Hàn Quốc, dạng phức hợp một hạt một màu nên mỗi hạt đều đủ đạm, lân, kali, bón ra cây hấp thu đồng đều.', '["Giúp cây sinh trưởng và phát triển tốt","Chắc hạt, to củ, lớn trái, nặng ký","Tăng chống chịu sâu bệnh, thời tiết bất lợi","Tăng năng suất và chất lượng nông sản"]', 'Bón thúc. Cà phê, cao su 500–700 kg/ha/lần; tiêu 300–500 g/trụ/lần; mía 400–500 kg/ha/lần; khoai mì 200–300 kg/ha/lần; cây ăn trái 0,5–1 kg/gốc/lần. Lượng bón thay đổi theo đất và tình trạng cây.', 'Đạm tổng số (Nts) 17%, Lân hữu hiệu (P2O5hh) 7%, Kali hữu hiệu (K2Ohh) 17%, Bo (B) 310 ppm, Kẽm (Zn) 800 ppm, độ ẩm 2%.', 'Bao 50kg', '["Hàn Việt","Phân bón","Báo giá theo đợt"]', '["ca-phe","sau-rieng"]', NULL, NULL, NULL, 'Phân NPK phức hợp một hạt một màu (hạt màu hồng), bao 50kg, mã HV02A. Giá bao lớn thay đổi theo đợt hàng và khu vực, liên hệ để nhận báo giá.', 50300, 80, 50, 15, 0, 7) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
