INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('HV-151515-50KG', 'npk-han-viet-15-15-15-bao-50kg', 'NPK Hàn-Việt 15-15-15', 'Bao 50kg', 'han-viet', 'main', 0, NULL, NULL, NULL, 50, '/assets/img/hv-151515-50kg.webp', '/assets/img/hv-151515-50kg.webp', 'Phân NPK phức hợp một hạt một màu (hạt màu hồng), bao 50kg, mã HV03A. Giá bao lớn thay đổi theo đợt hàng và khu vực, liên hệ để nhận báo giá.', 'NPK Hàn-Việt do Công ty TNHH Phân bón Hàn-Việt (KVF) sản xuất bằng công nghệ hơi nước theo tiêu chuẩn Hàn Quốc, dạng phức hợp một hạt một màu nên mỗi hạt đều đủ đạm, lân, kali, bón ra cây hấp thu đồng đều.', '["Giúp cây sinh trưởng và phát triển tốt","Giúp cây phục hồi sau thu hoạch, trái lớn đều","Tăng chống chịu sâu bệnh, thời tiết bất lợi","Tăng năng suất và chất lượng nông sản"]', 'Bón lót và thúc. Cây ăn trái 1–2 kg/cây/năm; cây công nghiệp 450–700 kg/ha/năm; lúa, bắp 300–400 kg/ha/vụ; rau màu 200–250 kg/ha/vụ. Lượng bón thay đổi theo đất và tình trạng cây.', 'Đạm tổng số (Nts) 15%, Lân hữu hiệu (P2O5hh) 15%, Kali hữu hiệu (K2Ohh) 15%, độ ẩm 2%.', 'Bao 50kg', '["Hàn Việt","Phân bón","Báo giá theo đợt"]', '["ca-phe","ho-tieu"]', NULL, NULL, NULL, 'Phân NPK phức hợp một hạt một màu (hạt màu hồng), bao 50kg, mã HV03A. Giá bao lớn thay đổi theo đợt hàng và khu vực, liên hệ để nhận báo giá.', 50300, 80, 50, 15, 0, 10) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('MP-HERO-100G', 'map-hero-340wp-goi-100g', 'Map Hero 340WP', 'Gói 100g', 'map-pacific', 'main', 95000, NULL, NULL, NULL, 100, '/assets/img/mp-hero-100g.webp', '/assets/img/mp-hero-100g.webp', 'Thuốc trừ bệnh phổ rộng phối hợp 3 hoạt chất, trừ mốc sương, thán thư, thối thân, đốm nâu, nứt thân chảy nhựa.', 'Map Pacific là công ty nông dược có trụ sở tại Singapore, có mặt tại Việt Nam nhiều năm với các dòng thuốc trừ sâu, trừ bệnh, trừ cỏ, thuốc sinh học và phân bón lá.', '["Azoxystrobin ức chế hô hấp của nấm","Fosetyl Aluminium lưu dẫn hai chiều, tăng sức đề kháng cho cây","Dimethomorph diệt nấm gây thối thân, mốc sương","Dùng cho nho, thanh long, cà chua, dưa hấu, bắp cải"]', 'Đọc kỹ nhãn trước khi dùng. Pha đúng liều, phun đúng lúc theo hướng dẫn trên nhãn cho từng loại cây, đảm bảo thời gian cách ly trước thu hoạch. Mang đồ bảo hộ khi pha và phun.', 'Azoxystrobin + Fosetyl Aluminium + Dimethomorph. Dạng bột thấm nước (WP).', 'Gói 100g', '["Map Pacific","Thuốc trừ bệnh"]', '["sau-rieng","ho-tieu","chanh-day"]', NULL, NULL, NULL, 'Thuốc trừ bệnh phổ rộng phối hợp 3 hoạt chất, trừ mốc sương, thán thư, thối thân, đốm nâu, nứt thân chảy nhựa.', 130, 15, 10, 4, 0, 11) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('MP-MATAXYL-100G', 'mataxyl-500wp-goi-100g', 'Mataxyl 500WP', 'Gói 100g', 'map-pacific', 'main', 108000, NULL, NULL, NULL, 100, '/assets/img/mp-mataxyl-100g.webp', '/assets/img/mp-mataxyl-100g.webp', 'Metalaxyl 50% nội hấp, lưu dẫn mạnh, chuyên phòng trừ chết nhanh, thối rễ, sương mai. Hay dùng tưới gốc hồ tiêu, sầu riêng đầu mùa mưa.', 'Map Pacific là công ty nông dược có trụ sở tại Singapore, có mặt tại Việt Nam nhiều năm với các dòng thuốc trừ sâu, trừ bệnh, trừ cỏ, thuốc sinh học và phân bón lá.', '["Hàm lượng Metalaxyl đậm đặc 50%","Thấm qua rễ, lá, thân và di chuyển khắp cây","Phòng trừ nấm nhóm Phytophthora, Pythium","Phun lá hoặc tưới gốc"]', 'Đọc kỹ nhãn trước khi dùng. Pha đúng liều, phun đúng lúc theo hướng dẫn trên nhãn cho từng loại cây, đảm bảo thời gian cách ly trước thu hoạch. Mang đồ bảo hộ khi pha và phun.', 'Metalaxyl 500 g/kg. Dạng bột thấm nước (WP).', 'Gói 100g', '["Map Pacific","Thuốc trừ bệnh","Bán chạy"]', '["ho-tieu","sau-rieng","chanh-day"]', NULL, NULL, NULL, 'Metalaxyl 50% nội hấp, lưu dẫn mạnh, chuyên phòng trừ chết nhanh, thối rễ, sương mai. Hay dùng tưới gốc hồ tiêu, sầu riêng đầu mùa mưa.', 130, 15, 10, 4, 0, 12) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('MP-ROTA-100G', 'map-rota-50wp-goi-100g', 'Map Rota 50WP', 'Gói 100g', 'map-pacific', 'main', 224000, NULL, NULL, NULL, 100, '/assets/img/mp-rota-100g.webp', '/assets/img/mp-rota-100g.webp', 'Kresoxim-methyl nhóm Strobilurin thế hệ mới, trừ thán thư, sương mai, phấn trắng, đốm lá trên cây ăn trái và hoa.', 'Map Pacific là công ty nông dược có trụ sở tại Singapore, có mặt tại Việt Nam nhiều năm với các dòng thuốc trừ sâu, trừ bệnh, trừ cỏ, thuốc sinh học và phân bón lá.', '["Vừa ngăn bào tử nảy mầm vừa ức chế sợi nấm đã xâm nhập","Giữ lá xanh, bóng","Phù hợp cây ăn trái, hoa lan, rau màu"]', 'Đọc kỹ nhãn trước khi dùng. Pha đúng liều, phun đúng lúc theo hướng dẫn trên nhãn cho từng loại cây, đảm bảo thời gian cách ly trước thu hoạch. Mang đồ bảo hộ khi pha và phun.', 'Kresoxim-methyl 500 g/kg. Dạng bột thấm nước (WP).', 'Gói 100g', '["Map Pacific","Thuốc trừ bệnh"]', '["sau-rieng"]', NULL, NULL, NULL, 'Kresoxim-methyl nhóm Strobilurin thế hệ mới, trừ thán thư, sương mai, phấn trắng, đốm lá trên cây ăn trái và hoa.', 130, 15, 10, 4, 0, 13) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.