INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('MP-STRONG-100G', 'map-strong-3wp-goi-100g', 'Map Strong 3WP', 'Gói 100g', 'map-pacific', 'main', 148000, NULL, NULL, NULL, 100, '/assets/img/mp-strong-100g.webp', '/assets/img/mp-strong-100g.webp', 'Thuốc trừ bệnh sinh học chứa kháng sinh Zhongshengmycin, chuyên bệnh do vi khuẩn: bạc lá, loét, héo xanh.', 'Map Pacific là công ty nông dược có trụ sở tại Singapore, có mặt tại Việt Nam nhiều năm với các dòng thuốc trừ sâu, trừ bệnh, trừ cỏ, thuốc sinh học và phân bón lá.', '["Nguồn gốc sinh học","Ức chế nhanh vi khuẩn gây bệnh","Dùng cho lúa, cây có múi, rau màu"]', 'Đọc kỹ nhãn trước khi dùng. Pha đúng liều, phun đúng lúc theo hướng dẫn trên nhãn cho từng loại cây, đảm bảo thời gian cách ly trước thu hoạch. Mang đồ bảo hộ khi pha và phun.', 'Zhongshengmycin 3%. Dạng bột thấm nước (WP).', 'Gói 100g', '["Map Pacific","Thuốc trừ bệnh","Sinh học"]', '["rau-mau","chanh-day"]', NULL, NULL, NULL, 'Thuốc trừ bệnh sinh học chứa kháng sinh Zhongshengmycin, chuyên bệnh do vi khuẩn: bạc lá, loét, héo xanh.', 130, 15, 10, 4, 0, 14) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('MP-ONI-500ML', 'map-oni-2sl-chai-500ml', 'Map Oni 2SL', 'Chai 500ml', 'map-pacific', 'main', 135000, NULL, NULL, NULL, 100, '/assets/img/mp-oni-500ml.webp', '/assets/img/mp-oni-500ml.webp', 'Thuốc trừ bệnh sinh học chứa Papain chiết từ mủ đu đủ xanh, trị bạc lá lúa, loét cây có múi, thối nhũn rau màu.', 'Map Pacific là công ty nông dược có trụ sở tại Singapore, có mặt tại Việt Nam nhiều năm với các dòng thuốc trừ sâu, trừ bệnh, trừ cỏ, thuốc sinh học và phân bón lá.', '["Papain phá vỡ màng tế bào vi khuẩn","Nguồn gốc sinh học, phù hợp canh tác an toàn","Chai 500ml dùng cho diện tích lớn"]', 'Đọc kỹ nhãn trước khi dùng. Pha đúng liều, phun đúng lúc theo hướng dẫn trên nhãn cho từng loại cây, đảm bảo thời gian cách ly trước thu hoạch. Mang đồ bảo hộ khi pha và phun.', 'Hoạt chất Papain (chiết xuất từ mủ đu đủ). Dạng dung dịch (SL).', 'Chai 500ml', '["Map Pacific","Thuốc trừ bệnh","Sinh học"]', '["rau-mau","chanh-day"]', NULL, NULL, NULL, 'Thuốc trừ bệnh sinh học chứa Papain chiết từ mủ đu đủ xanh, trị bạc lá lúa, loét cây có múi, thối nhũn rau màu.', 600, 8, 8, 20, 1, 15) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excl