INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('MP-DONA-250ML', 'map-dona-265ec-chai-250ml', 'Map Dona 265EC', 'Chai 250ml', 'map-pacific', 'main', 185000, NULL, NULL, NULL, 100, '/assets/img/mp-dona-250ml.webp', '/assets/img/mp-dona-250ml.webp', 'Kết hợp Chlorpyrifos Methyl và Indoxacarb, trừ sâu cuốn lá, sâu xanh đã kháng thuốc thông thường.', 'Map Pacific là công ty nông dược có trụ sở tại Singapore, có mặt tại Việt Nam nhiều năm với các dòng thuốc trừ sâu, trừ bệnh, trừ cỏ, thuốc sinh học và phân bón lá.', '["Tác động tiếp xúc, xông hơi và vị độc","Hạ gục sâu nhanh","Hiệu lực kéo dài"]', 'Đọc kỹ nhãn trước khi dùng. Pha đúng liều, phun đúng lúc theo hướng dẫn trên nhãn cho từng loại cây, đảm bảo thời gian cách ly trước thu hoạch. Mang đồ bảo hộ khi pha và phun.', 'Chlorpyrifos Methyl + Indoxacarb. Dạng nhũ dầu (EC).', 'Chai 250ml', '["Map Pacific","Thuốc trừ sâu"]', '["rau-mau"]', NULL, NULL, NULL, 'Kết hợp Chlorpyrifos Methyl và Indoxacarb, trừ sâu cuốn lá, sâu xanh đã kháng thuốc thông thường.', 320, 7, 7, 17, 1, 16) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
