INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('MP-SUPO-500ML', 'map-su-po-chai-500ml-phan-bon-la', 'Map Su-po', 'Chai 500ml · Phân bón lá', 'map-pacific', 'main', 153000, NULL, NULL, NULL, 100, '/assets/img/mp-supo-500ml.webp', '/assets/img/mp-supo-500ml.webp', 'Phân bón lá siêu Bo, giúp hạt phấn khỏe, hạn chế rụng hoa, tăng tỷ lệ đậu trái.', 'Map Pacific là công ty nông dược có trụ sở tại Singapore, có mặt tại Việt Nam nhiều năm với các dòng thuốc trừ sâu, trừ bệnh, trừ cỏ, thuốc sinh học và phân bón lá.', '["Bổ sung Bo cho giai đoạn ra hoa, đậu trái","Cuống trái dai hơn","Phun lúc nhú hoa và lúc tượng trái non"]', 'Pha theo liều ghi trên nhãn, phun đều hai mặt lá vào sáng sớm hoặc chiều mát. Không phun khi trời sắp mưa hoặc nắng gắt.', 'Bo (B) và phụ gia. Xem hàm lượng chi tiết trên nhãn.', 'Chai 500ml', '["Map Pacific","Phân bón lá"]', '["sau-rieng","chanh-day"]', NULL, NULL, NULL, 'Phân bón lá siêu Bo, giúp hạt phấn khỏe, hạn chế rụng hoa, tăng tỷ lệ đậu trái.', 600, 8, 8, 20, 1, 21) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
