INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NA-AZTRON-50G', 'aztron-wg-goi-50g', 'Aztron WG', 'Gói 50g', 'ngan-anh', 'main', 62000, NULL, NULL, NULL, 100, '/assets/img/na-aztron-50g.webp', '/assets/img/na-aztron-50g.webp', 'Thuốc trừ sâu sinh học Bt aizawai nhập khẩu Mỹ, trị sâu tơ, sâu xanh da láng, sâu khoang, sâu vẽ bùa.', 'Công ty TNHH Ngân Anh (thành lập năm 2004, thương hiệu Tân Qui) nhập khẩu và phân phối thuốc bảo vệ thực vật, phân bón cao cấp từ châu Âu, Mỹ, Israel.', '["Sâu ngừng ăn ngay sau khi nhiễm","Giải quyết sâu kháng thuốc hóa học","Phù hợp sản xuất theo hướng GAP"]', 'Đọc kỹ nhãn trước khi dùng. Pha đúng liều, phun đúng lúc theo hướng dẫn trên nhãn cho từng loại cây, đảm bảo thời gian cách ly trước thu hoạch. Mang đồ bảo hộ khi pha và phun.', 'Bacillus thuringiensis var. aizawai 35.000 DBM Units/mg. Dạng cốm phân tán (WG).', 'Gói 50g', '["Ngân Anh","Thuốc trừ sâu","Sinh học"]', '["rau-mau"]', NULL, NULL, NULL, 'Thuốc trừ sâu sinh học Bt aizawai nhập khẩu Mỹ, trị sâu tơ, sâu xanh da láng, sâu khoang, sâu vẽ bùa.', 80, 15, 10, 4, 0, 36) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.