INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NA-NUTRIVANT-500G', 'nutrivant-rice-0-46-30-goi-500g-phan-bon-la', 'Nutrivant Rice 0-46-30', 'Gói 500g · Phân bón lá', 'ngan-anh', 'main', 95000, NULL, NULL, NULL, 100, '/assets/img/na-nutrivant-500g.webp', '/assets/img/na-nutrivant-500g.webp', 'Phân bón lá PK nhập khẩu Israel, lân và kali cao, hỗ trợ phân hóa mầm hoa, công nghệ phụ gia Fertivant bám dính tốt.', 'Công ty TNHH Ngân Anh (thành lập năm 2004, thương hiệu Tân Qui) nhập khẩu và phân phối thuốc bảo vệ thực vật, phân bón cao cấp từ châu Âu, Mỹ, Israel.', '["Lân 46%, kali 30% cho giai đoạn tạo mầm hoa","Hạt tan mịn, bám dính lá tốt","Hỗ trợ ra hoa đều"]', 'Pha theo liều ghi trên nhãn, phun đều hai mặt lá vào sáng sớm hoặc chiều mát. Không phun khi trời sắp mưa hoặc nắng gắt.', 'P2O5 46%, K2O 30%, phụ gia Fertivant.', 'Gói 500g', '["Ngân Anh","Phân bón lá"]', '["sau-rieng","ca-phe"]', NULL, NULL, NULL, 'Phân bón lá PK nhập khẩu Israel, lân và kali cao, hỗ trợ phân hóa mầm hoa, công nghệ phụ gia Fertivant bám dính tốt.', 550, 20, 14, 4, 0, 37) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NA-NUTACK-300G', 'nutac-k-7-13-34-goi-300g-phan-bon-la', 'Nutac-K 7-13-34', 'Gói 300g · Phân bón lá', 'ngan-anh', 'main', 147000, NULL, NULL, NULL, 100, '/assets/img/na-nutack-300g.webp', '/assets/img/na-nutack-300g.webp', 'Phân bón lá kali cao của Miller (Mỹ), công nghệ Sugar Express, giúp trái lên màu, tăng độ ngọt, chắc hạt.', 'Công ty TNHH Ngân Anh (thành lập năm 2004, thương hiệu Tân Qui) nhập khẩu và phân phối thuốc bảo vệ thực vật, phân bón cao cấp từ châu Âu, Mỹ, Israel.', '["Kali cao 34% cho giai đoạn nuôi trái","Hỗ trợ lên màu, tăng độ Brix","Gói 300g pha được khoảng 200 lít nước"]', 'Pha theo liều ghi trên nhãn, phun đều hai mặt lá vào sáng sớm hoặc chiều mát. Không phun khi trời sắp mưa hoặc nắng gắt.', 'N 7%, P2O5 13%, K2O 34%. Sản xuất bởi Miller Chemical & Fertilizer (Mỹ).', 'Gói 300g', '["Ngân Anh","Phân bón lá"]', '["sau-rieng","chanh-day"]', NULL, NULL, NULL, 'Phân bón lá kali cao của Miller (Mỹ), công nghệ Sugar Express, giúp trái lên màu, tăng độ ngọt, chắc hạt.', 350, 18, 12, 4, 0, 38) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NA-MIRACLE153015-1KG', 'miracle-gro-15-30-15-te-hop-1kg-phan-bon-la', 'Miracle-Gro 15-30-15+TE', 'Hộp 1kg · Phân bón lá', 'ngan-anh', 'main', 209000, NULL, NULL, NULL, 100, '/assets/img/na-miracle153015-1kg.webp', '/assets/img/na-miracle153015-1kg.webp', 'Phân bón lá NPK lân cao 30%, kích thích phân hóa mầm hoa, tăng đậu trái. Dùng tốt cho mai, hoa kiểng, cây ăn trái.', 'Công ty TNHH Ngân Anh (thành lập năm 2004, thương hiệu Tân Qui) nhập khẩu và phân phối thuốc bảo vệ thực vật, phân bón cao cấp từ châu Âu, Mỹ, Israel.', '["Lân cao cho giai đoạn ra hoa","Tan hoàn toàn trong nước","Bổ sung vi lượng"]', 'Pha theo liều ghi trên nhãn, phun đều hai mặt lá vào sáng sớm hoặc chiều mát. Không phun khi trời sắp mưa hoặc nắng gắt.', 'N 15%, P2O5 30%, K2O 15%, vi lượng (TE).', 'Hộp 1kg', '["Ngân Anh","Phân bón lá"]', '["sau-rieng"]', NULL, NULL, NULL, 'Phân bón lá NPK lân cao 30%, kích thích phân hóa mầm hoa, tăng đậu trái. Dùng tốt cho mai, hoa kiểng, cây ăn trái.', 1100, 18, 12, 10, 0, 39) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('MP-ENCOURAGE', 'map-encourage-phan-bon-la-sinh-hoc', 'Map Encourage', 'Phân bón lá sinh học', 'map-pacific', 'main', 0, NULL, NULL, NULL, 100, '/assets/img/mp-encourage.webp', '/assets/img/mp-encourage.webp', 'Phân bón lá đa, vi lượng, sinh học chứa Humic, NPK, Fe, Mn. Kích rễ mạnh, thúc ra hoa đồng loạt, tăng đậu trái cho sầu riêng, tiêu, cà phê, rau màu.', 'Sản phẩm Nông Xanh Tây Nguyên đang dùng và tư vấn cho bà con. Phù hợp khi cây phát triển chậm, rễ yếu, ra hoa không đều, đậu trái kém.', '["Kích thích bộ rễ phát triển mạnh","Thúc ra hoa đồng loạt, tăng đậu trái","Cây phục hồi nhanh, tăng sức đề kháng"]', 'Pha phun lá hoặc tưới gốc theo hướng dẫn trên bao bì. Liên hệ kỹ thuật Nông Xanh để được hướng dẫn liều theo từng loại cây và giai đoạn.', 'Humic, NPK, vi lượng Fe, Mn (xem chi tiết trên nhãn).', 'Liên hệ quy cách', '["Map Pacific","Phân bón lá"]', '["sau-rieng","ho-tieu","ca-phe","chanh-day"]', NULL, NULL, NULL, 'Phân bón lá đa, vi lượng, sinh học chứa Humic, NPK, Fe, Mn. Kích rễ mạnh, thúc ra hoa đồng loạt, tăng đậu trái cho sầu riêng, tiêu, cà phê, rau màu.', 600, 12, 8, 20, 1, 60) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NX-NANOZN', 'nano-zn-apn-kem-nano-nhap-khau-duc', 'Nano Zn APN', 'Kẽm nano nhập khẩu Đức', 'nong-xanh-chon', 'main', 0, NULL, NULL, NULL, 100, '/assets/img/nx-nanozn.webp', '/assets/img/nx-nanozn.webp', 'Kẽm dạng nano 700 g/l, cây hấp thu nhanh, xanh lá, tăng quang hợp, hạn chế rụng hoa, rụng trái non và giúp cây chống stress khi nắng nóng, mưa dầm.', 'Nhập khẩu 100% từ Đức, ứng dụng công nghệ nano. Hay dùng khi cây vàng lá, đọt non nhỏ, lá mo do thiếu kẽm, đặc biệt trên chanh dây.', '["Dưỡng cây xanh, phục hồi nhanh","Tăng đậu hoa, chắc trái","Chống stress do thời tiết, sốc phân, sốc thuốc"]', 'Pha phun lá theo hướng dẫn trên nhãn. Liên hệ kỹ thuật Nông Xanh để được tư vấn liều theo cây trồng.', 'Zinc (Zn) 700 g/l, tỷ trọng 1,6, pH 6.', 'Liên hệ quy cách', '["Phân bón lá"]', '["chanh-day","sau-rieng","ca-phe","ho-tieu"]', NULL, NULL, NULL, 'Kẽm dạng nano 700 g/l, cây hấp thu nhanh, xanh lá, tăng quang hợp, hạn chế rụng hoa, rụng trái non và giúp cây chống stress khi nắng nóng, mưa dầm.', 1200, 10, 10, 25, 1, 61) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NX-SILIC-HYEOPHWA', 'phan-silic-han-quoc-hyeop-hwa-silic-canxi-magie-dang-hat', 'Phân Silic Hàn Quốc HYEOP HWA', 'Silic, Canxi, Magie dạng hạt', 'nong-xanh-chon', 'main', 0, NULL, NULL, NULL, 100, '/assets/img/nx-silic.webp', '/assets/img/nx-silic.webp', 'SiO₂ 25,76%, CaO 37,54%, MgO 2,44%. Cải tạo đất, nâng pH, thân lá cứng cáp, tăng sức chống chịu sâu bệnh và thời tiết bất lợi.', 'Sản xuất tại Hàn Quốc, dạng hạt 2–4 mm tan chậm, dễ bón. Phù hợp chanh dây, sầu riêng, cà phê, hồ tiêu.', '["Bổ sung Silic, thân cứng lá dày","Cải tạo đất chua, nâng pH","Tăng sức đề kháng tự nhiên, hạn chế đổ ngã"]', 'Rải gốc theo tán cây rồi tưới ẩm. Liên hệ kỹ thuật Nông Xanh để được tư vấn lượng bón theo độ tuổi cây và tình trạng đất.', 'SiO₂ 25,76%, CaO 37,54%, MgO 2,44%, độ ẩm 1,17%.', 'Liên hệ quy cách', '["Phân bón"]', '["chanh-day","sau-rieng","ca-phe","ho-tieu"]', NULL, NULL, NULL, 'SiO₂ 25,76%, CaO 37,54%, MgO 2,44%. Cải tạo đất, nâng pH, thân lá cứng cáp, tăng sức chống chịu sâu bệnh và thời tiết bất lợi.', 25000, 60, 40, 12, 0, 62) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NX-VISINH-TRAUVANG', 'vi-sinh-con-trau-vang-che-pham-10-chung-vi-sinh', 'Vi sinh Con Trâu Vàng', 'Chế phẩm 10 chủng vi sinh', 'nong-xanh-chon', 'main', 650000, 690000, NULL, NULL, 100, '/assets/img/nx-trauvang.webp', '/assets/img/nx-trauvang.webp', '10 chủng vi sinh đặc hiệu (Trichoderma, Bacillus, Aspergillus...), cải tạo đất chai cứng, phân giải hữu cơ nhanh, ức chế nấm bệnh và tuyến trùng hại rễ.', 'Giải pháp Nông Xanh dùng để phục hồi đất cho vườn chanh dây, sầu riêng. Xem video hướng dẫn nhân vi sinh trên kênh YouTube của Nông Xanh.', '["Đất tơi xốp, giàu dinh dưỡng","Rễ khỏe, hạn chế nấm bệnh và tuyến trùng","Tăng hệ vi sinh có lợi, giảm phân hóa học"]', 'Nhân sinh khối hoặc ủ cùng phân hữu cơ rồi bón gốc, tưới gốc. Xem video hướng dẫn hoặc gọi kỹ thuật Nông Xanh.', 'Trichoderma spp., Bacillus subtilis, Bacillus polymyxa, Bacillus licheniformis, Aspergillus niger, Aspergillus oryzae và các chủng khác.', 'Theo bao bì', '["Sinh học","Phân bón"]', '["chanh-day","sau-rieng","ca-phe","ho-tieu"]', NULL, NULL, NULL, '10 chủng vi sinh đặc hiệu (Trichoderma, Bacillus, Aspergillus...), cải tạo đất chai cứng, phân giải hữu cơ nhanh, ức chế nấm bệnh và tuyến trùng hại rễ.', 1500, 25, 18, 10, 0, 63) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NX-CHANHVANG-5KG', 'chanh-day-vang-mat-ong-thung-5kg-trai-tu-vuon-nong-xanh', 'Chanh dây vàng mật ong', 'Thùng 5kg · trái từ vườn Nông Xanh', 'nong-san-nong-xanh', 'main', 220000, NULL, NULL, NULL, 50, '/assets/img/nx-chanhvang.webp', '/assets/img/nx-chanhvang.webp', 'Giống chanh dây vàng gốc Đài Loan, ngọt 18–22 độ brix, thơm mùi mật ong. Canh tác tại vườn Nông Xanh Tây Nguyên.', 'Trái từ chính vườn chanh dây của Nông Xanh, nơi đội kỹ thuật thử nghiệm quy trình phân bón và thuốc trước khi tư vấn cho bà con. Theo Nông Xanh, trái đã qua kiểm tra hơn 500 hoạt chất thuốc bảo vệ thực vật.', '["Vị ngọt đậm, thơm mật ong","Giàu vitamin A, C, kali, chất xơ","Ăn tươi, làm nước ép, sinh tố"]', 'Bảo quản nơi thoáng mát. Trái vàng đều, hơi nhăn vỏ là ngọt nhất.', NULL, '5kg', '["Nông sản"]', '[]', NULL, NULL, NULL, 'Giống chanh dây vàng gốc Đài Loan, ngọt 18–22 độ brix, thơm mùi mật ong. Canh tác tại vườn Nông Xanh Tây Nguyên.', 5300, 40, 30, 15, 1, 70) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NX-CHANHVANG-10KG', 'chanh-day-vang-mat-ong-thung-10kg-trai-tu-vuon-nong-xanh', 'Chanh dây vàng mật ong', 'Thùng 10kg · trái từ vườn Nông Xanh', 'nong-san-nong-xanh', 'main', 400000, NULL, NULL, NULL, 50, '/assets/img/nx-chanhvang.webp', '/assets/img/nx-chanhvang.webp', 'Thùng 10kg chanh dây vàng mật ong, ngọt 18–22 độ brix, tiết kiệm hơn khi mua cho gia đình, quán nước.', 'Trái từ chính vườn chanh dây của Nông Xanh Tây Nguyên.', '["Vị ngọt đậm, thơm mật ong","Lợi hơn thùng 5kg","Phù hợp quán nước, gia đình đông người"]', 'Bảo quản nơi thoáng mát.', NULL, '10kg', '["Nông sản"]', '[]', NULL, NULL, NULL, 'Thùng 10kg chanh dây vàng mật ong, ngọt 18–22 độ brix, tiết kiệm hơn khi mua cho gia đình, quán nước.', 10500, 40, 30, 25, 1, 71) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NX-CHANHTIM', 'chanh-day-tim-nong-xanh-trai-tuoi-tai-vuon', 'Chanh dây tím Nông Xanh', 'Trái tươi tại vườn', 'nong-san-nong-xanh', 'main', 30000, NULL, NULL, NULL, 50, '/assets/img/nx-chanhtim.webp', '/assets/img/nx-chanhtim.webp', 'Vỏ tím đậm, ruột vàng óng, vị chua ngọt hài hòa, thơm đậm. Giàu vitamin C và chất chống oxy hóa.', 'Trái từ vườn Nông Xanh Tây Nguyên. Giá theo niêm yết trên nongxanh.net.', '["Chua ngọt hài hòa, thơm đậm","Giàu vitamin C","Làm nước uống, tráng miệng"]', 'Bảo quản nơi thoáng mát hoặc ngăn mát tủ lạnh.', NULL, 'Theo đơn vị bán', '["Nông sản"]', '[]', NULL, NULL, NULL, 'Vỏ tím đậm, ruột vàng óng, vị chua ngọt hài hòa, thơm đậm. Giàu vitamin C và chất chống oxy hóa.', 1000, 25, 18, 10, 1, 72) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('NX-SETQUA-CHANHVANG', 'set-qua-chanh-day-vang-ngot-hop-qua-den-1-5kg', 'Set quà chanh dây vàng ngọt', 'Hộp quà đến 1,5kg', 'nong-san-nong-xanh', 'gift', 99000, NULL, NULL, NULL, 50, '/assets/img/nx-setqua.webp', '/assets/img/nx-setqua.webp', 'Trái chín tự nhiên, vỏ vàng đẹp, đóng hộp quà có tem nhãn nguồn gốc. Làm quà biếu hoặc thưởng thức hằng ngày.', 'Chọn lọc từ vườn chanh dây Nông Xanh Tây Nguyên.', '["Hộp quà chỉn chu, lịch sự","Tem nhãn nguồn gốc rõ ràng","Trái đẹp, kích thước đồng đều"]', 'Bảo quản nơi thoáng mát.', NULL, 'Đến 1,5kg', '["Nông sản","Quà tặng"]', '[]', NULL, NULL, NULL, 'Trái chín tự nhiên, vỏ vàng đẹp, đóng hộp quà có tem nhãn nguồn gốc. Làm quà biếu hoặc thưởng thức hằng ngày.', 1700, 30, 22, 12, 1, 73) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('COMBO-CHETNHANH', 'combo-phong-chet-nhanh-dau-mua-mua-ho-tieu-ca-phe-tuoi-goc', 'Combo phòng chết nhanh đầu mùa mưa', 'Hồ tiêu, cà phê · tưới gốc', 'combo', 'combo', 578000, 608000, NULL, NULL, 0, '/assets/img/combo-chetnhanh.webp', '/assets/img/combo-chetnhanh.webp', 'Bộ tưới gốc phòng nấm Phytophthora (chết nhanh, thối rễ) và xử lý tuyến trùng đầu mùa mưa cho vườn hồ tiêu, cà phê.', 'Combo do đội kỹ thuật Nông Xanh gợi ý theo vấn đề hay gặp ngoài vườn. Liều dùng từng sản phẩm theo nhãn; gọi kỹ thuật để được chỉnh theo diện tích và tình trạng cây.', '["Mataxyl và Danjiri luân phiên tưới gốc trị nấm","Map Logic rải gốc xử lý tuyến trùng, cải tạo đất","Lợi hơn mua lẻ"]', NULL, NULL, NULL, '["Combo"]', '["ho-tieu","ca-phe"]', '[{"sku":"MP-MATAXYL-100G","qty":2},{"sku":"SM-DANJIRI-100ML","qty":1},{"sku":"MP-LOGIC-2KG","qty":1}]', NULL, NULL, 'Bộ tưới gốc phòng nấm Phytophthora (chết nhanh, thối rễ) và xử lý tuyến trùng đầu mùa mưa cho vườn hồ tiêu, cà phê.', 2000, 30, 22, 20, 1, 50) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
