, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('COMBO-RAHOA-DAUTRAI', 'combo-ra-hoa-dau-trai-sau-rieng-chanh-day', 'Combo ra hoa, đậu trái', 'Sầu riêng, chanh dây', 'combo', 'combo', 466000, 490000, NULL, NULL, 0, '/assets/img/combo-rahoa-dautrai.webp', '/assets/img/combo-rahoa-dautrai.webp', 'Bộ phân bón lá cho giai đoạn phân hóa mầm hoa, nuôi bông, đậu trái và nuôi trái lên màu.', 'Combo do đội kỹ thuật Nông Xanh gợi ý theo vấn đề hay gặp ngoài vườn. Liều dùng từng sản phẩm theo nhãn; gọi kỹ thuật để được chỉnh theo diện tích và tình trạng cây.', '["Nutrivant PK phân hóa mầm hoa","Su-po siêu Bo giữ hoa, tăng đậu trái","Nutac-K kali cao nuôi trái","Lợi hơn mua lẻ"]', NULL, NULL, NULL, '["Combo"]', '["sau-rieng","chanh-day"]', '[{"sku":"NA-NUTRIVANT-500G","qty":2},{"sku":"MP-SUPO-500ML","qty":1},{"sku":"NA-NUTACK-300G","qty":1}]', NULL, NULL, 'Bộ phân bón lá cho giai đoạn phân hóa mầm hoa, nuôi bông, đậu trái và nuôi trái lên màu.', 2000, 30, 22, 20, 1, 52) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('COMBO-REPSAP-CAPHE', 'combo-tri-rep-sap-ray-ca-phe-ca-phe-ho-tieu', 'Combo trị rệp sáp, rầy cà phê', 'Cà phê, hồ tiêu', 'combo', 'combo', 313000, 329000, NULL, NULL, 0, '/assets/img/combo-repsap-caphe.webp', '/assets/img/combo-repsap-caphe.webp', 'Bộ trị rệp sáp ẩn trong chùm quả, rầy xanh, bọ trĩ cho cà phê, hồ tiêu: thuốc xông hơi, thuốc nội hấp và thuốc cắt vòng đời.', 'Combo do đội kỹ thuật Nông Xanh gợi ý theo vấn đề hay gặp ngoài vườn. Liều dùng từng sản phẩm theo nhãn; gọi kỹ thuật để được chỉnh theo diện tích và tình trạng cây.', '["Danitol-S xông hơi diệt rệp ẩn","Jono nội hấp trừ rầy, bọ trĩ","Judo chặn lột xác, cắt vòng đời rệp","Lợi hơn mua lẻ"]', NULL, NULL, NULL, '["Combo"]', '["ca-phe","ho-tieu"]', '[{"sku":"SM-DANITOLS-450ML","qty":1},{"sku":"MP-JONO-40G","qty":1},{"sku":"MP-JUDO-100G","qty":2}]', NULL, NULL, 'Bộ trị rệp sáp ẩn trong chùm quả, rầy xanh, bọ trĩ cho cà phê, hồ tiêu: thuốc xông hơi, thuốc nội hấp và thuốc cắt vòng đời.', 2000, 30, 22, 20, 1, 53) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=excluded.fragile, sort=excluded.sort;
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('COMBO-RAU-SINHHOC', 'combo-rau-mau-sinh-hoc-rau-mau-an-toan-khi-thu-hoach', 'Combo rau màu sinh học', 'Rau màu, an toàn khi thu hoạch', 'combo', 'combo', 308000, 324000, NULL, NULL, 0, '/assets/img/combo-rau-sinhhoc.webp', '/assets/img/combo-rau-sinhhoc.webp', 'Bộ thuốc sinh học cho rau màu: trừ sâu tơ, sâu xanh bằng Bt, trừ bệnh vi khuẩn bằng Papain và tinh dầu cam tăng độ phủ.', 'Combo do đội kỹ thuật Nông Xanh gợi ý theo vấn đề hay gặp ngoài vườn. Liều dùng từng sản phẩm theo nhãn; gọi kỹ thuật để được chỉnh theo diện tích và tình trạng cây.', '["Hai dòng Bt luân phiên tránh kháng thuốc","Map Oni trị thối nhũn, vi khuẩn","Map Green tăng độ phủ, trừ sâu nhẹ","Lợi hơn mua lẻ"]', NULL, NULL, NULL, '["Combo"]', '["rau-mau"]', '[{"sku":"SM-DIPEL-50G","qty":2},{"sku":"NA-AZTRON-50G","qty":1},{"sku":"MP-ONI-500ML","qty":1},{"sku":"MP-GREEN-100ML","qty":1}]', NULL, NULL, 'Bộ thuốc sinh học cho rau màu: trừ sâu tơ, sâu xanh bằng Bt, trừ bệnh vi khuẩn bằng Papain và tinh dầu cam tăng độ phủ.', 2000, 30, 22, 20, 1, 54) ON CONFLICT(sku) DO UPDATE SET slug=excluded.slug, name=excluded.name, subtitle=excluded.subtitle, line=excluded.line, kind=excluded.kind, price=excluded.price, compare_price=excluded.compare_price, image=excluded.image, image_bg=excluded.image_bg, short_desc=excluded.short_desc, story=excluded.story, benefits=excluded.benefits, usage=excluded.usage, ingredients=excluded.ingredients, weight=excluded.weight, badges=excluded.badges, personas=excluded.personas, combo_items=excluded.combo_items, seo_desc=excluded.seo_desc, weight_g=excluded.weight_g, length_cm=excluded.length_cm, width_cm=excluded.width_cm, height_cm=excluded.height_cm, fragile=exclude